import{_ as e,C as r,c as l,o as t,a0 as i,b as n,w as s,a,G as o,a1 as g}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Treningsleir: Helgeguide","description":"","frontmatter":{},"headers":[],"relativePath":"no/training-camp.md","filePath":"no/training-camp.md"}');const k=e({name:"no/training-camp.md"},[["render",function(e,d,k,u,p,m){const h=r("Mermaid");return t(),l("div",null,[d[2]||(d[2]=i('<h1 id="treningsleir-helgeguide" tabindex="-1">Treningsleir: Helgeguide <a class="header-anchor" href="#treningsleir-helgeguide" aria-label="Permalink to &quot;Treningsleir: Helgeguide&quot;">​</a></h1><h2 id="hvordan-gjennomføre-en-helgetreningsleir-for-10–20-spillere" tabindex="-1">Hvordan gjennomføre en helgetreningsleir for 10–20 spillere <a class="header-anchor" href="#hvordan-gjennomføre-en-helgetreningsleir-for-10–20-spillere" aria-label="Permalink to &quot;Hvordan gjennomføre en helgetreningsleir for 10–20 spillere&quot;">​</a></h2><p>Denne omfattende guiden hjelper deg med å organisere og gjennomføre en helgetreningsleir som kombinerer teori, praksis og konkurranse. Bland det mentale spillinnholdet fra denne nettsiden med trening i løypa for maksimal effekt.</p><div class="tip custom-block"><p class="custom-block-title">Treningsleirfilosofien</p><p><strong>Teori uten praksis er bare informasjon. Praksis uten teori er bare repetisjon. Konkurranse uten refleksjon er bare lek.</strong> Denne helgen integrerer alle tre for transformerende læring.</p></div>',4)),(t(),n(g,null,{default:s(()=>[o(h,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:s(()=>[...d[0]||(d[0]=[a(" Loading... ",-1)])]),_:1})),d[3]||(d[3]=i('<h2 id="planlegging-før-leiren" tabindex="-1">Planlegging før leiren <a class="header-anchor" href="#planlegging-før-leiren" aria-label="Permalink to &quot;Planlegging før leiren&quot;">​</a></h2><h3 id="gruppestørrelse-og-struktur" tabindex="-1">Gruppestørrelse og -struktur <a class="header-anchor" href="#gruppestørrelse-og-struktur" aria-label="Permalink to &quot;Gruppestørrelse og -struktur&quot;">​</a></h3><p><strong>Optimal:</strong> 10–20 spillere</p><ul><li><strong>Liten leir (10–12):</strong> Mer intimt, dypere deling</li><li><strong>Stor leir (16–20):</strong> Mer mangfoldige perspektiver, krever undergrupper</li></ul><p><strong>Lagstruktur:</strong></p><ul><li>Del inn i lag på 3-4 for trening og konkurranse</li><li>Bland ferdighetsnivåer og spillestiler</li><li>Roterer lagene gjennom helgen</li></ul><h3 id="bemanningskrav" tabindex="-1">Bemanningskrav <a class="header-anchor" href="#bemanningskrav" aria-label="Permalink to &quot;Bemanningskrav&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rolle</th><th>Ansvar</th><th>Mengde</th></tr></thead><tbody><tr><td><strong>Koordinator for mental ytelse</strong></td><td>Tilrettelegge teoriøkter, gruppedynamikk</td><td>1</td></tr><tr><td><strong>Teknisk trener</strong></td><td>Overvåke trening, gi tilbakemeldinger</td><td>1-2</td></tr><tr><td><strong>Konkurranseleder</strong></td><td>Gjennomføre turneringen, administrere logistikk</td><td>1</td></tr><tr><td><strong>Støttepersonell</strong></td><td>Måltider, oppsett, administrasjon</td><td>1-2</td></tr></tbody></table><h3 id="krav-til-plassering" tabindex="-1">Krav til plassering <a class="header-anchor" href="#krav-til-plassering" aria-label="Permalink to &quot;Krav til plassering&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Fasilitetsbehov</p><p><strong>Løype:</strong></p><ul><li>Flere terreng (minimum 3-4 løyper)</li><li>Ulike underlag hvis mulig (grus, sand, hardt)</li><li>Belysning for kveldslek</li></ul><p><strong>Innendørsrom:</strong></p><ul><li>Plass til 20 personer i sirkel (teoriøkter)</li><li>Separat fra løypen</li><li>Tavle/projektor</li><li>Komfortable sitteplasser</li></ul><p><strong>Overnatting:</strong></p><ul><li>På stedet eller i nærheten (gangavstand)</li><li>Delte rom oppmuntrer til tilknytning</li><li>Stille rom for refleksjon</li></ul><p><strong>Catering:</strong></p><ul><li>Næringsfokuserte måltider (se <a href="./food">Matguide</a>)</li><li>Unngå sukkerkrasj</li><li>Drikkestasjoner</li></ul></div><h3 id="sjekkliste-for-materialer" tabindex="-1">Sjekkliste for materialer <a class="header-anchor" href="#sjekkliste-for-materialer" aria-label="Permalink to &quot;Sjekkliste for materialer&quot;">​</a></h3><details class="details custom-block"><summary>Komplett materialliste</summary><p><strong>Teoriøkter:</strong></p><ul><li>[ ] Stoler for sirkel (ingen bord)</li><li>[ ] Boule og cochonett for senter</li><li>[ ] Flippover og tusjer</li><li>[ ] Klistrelapper</li><li>[ ] Arbeidsark (brukermanual, indre kritiker, osv.)</li><li>[ ] Papir og penner</li><li>[ ] Projektor (for nettstedsinnhold)</li></ul><p><strong>Øvingsøkter:</strong></p><ul><li>[ ] Målebånd</li><li>[ ] Kjegler/markører for øvelser</li><li>[ ] Videokamera/stativ</li><li>[ ] Utklippstavle og papir (sporing)</li><li>[ ] Plystre</li></ul><p><strong>Konkurranse:</strong></p><ul><li>[ ] Poengskjemaer</li><li>[ ] Turneringskonkurranse</li><li>[ ] Premier/anerkjennelse</li><li>[ ] Førstehjelpsskrin</li></ul><p><strong>Logistikk:</strong></p><ul><li>[ ] Navneskilt</li><li>[ ] Deltakerliste med kontakter</li><li>[ ] Nødkontaktinformasjon</li><li>[ ] Vannflasker</li><li>[ ] Solkrem</li><li>[ ] Vev (for emosjonelt arbeid!)</li></ul></details><h2 id="helgeprogram" tabindex="-1">Helgeprogram <a class="header-anchor" href="#helgeprogram" aria-label="Permalink to &quot;Helgeprogram&quot;">​</a></h2><h3 id="fredag-kveld-3-timer" tabindex="-1">Fredag kveld (3 timer) <a class="header-anchor" href="#fredag-kveld-3-timer" aria-label="Permalink to &quot;Fredag kveld (3 timer)&quot;">​</a></h3><p><strong>18:00–18:30 – Ankomst og velkomst</strong></p><ul><li>Innsjekking</li><li>Romtildelinger</li><li>Oversikt over helgen</li></ul><p><strong>18:30–19:30 – Middag</strong></p><ul><li>Ernæringsfokusert måltid</li><li>Uformelle introduksjoner</li></ul><p><strong>19:30–22:30 – Teoriøkt: Grunnleggende</strong></p><p>Bruk <a href="./workshop">Workshop-guiden</a> for detaljert veiledning:</p><ol><li><strong>Grunnregler (15 min)</strong> - Etabler psykologisk trygghet</li><li><strong>Innsjekkingsmatrise (20 min)</strong> - Vurder gruppens energi</li><li><strong>Isfjellet (30 min)</strong> - Utforsk indre tanker</li><li><strong>Brukermanual (45 min)</strong> – Bygg teamforståelse</li><li><strong>Frykt i en hatt (45 min)</strong> - Bryt isolasjonen</li><li><strong>Utsjekking (15 min)</strong> – Slutt på prosessen</li></ol><p><strong>22:30 - Fritid</strong></p><ul><li>Uformell sosialisering</li><li>Hvile og refleksjon</li></ul>',23)),(t(),n(g,null,{default:s(()=>[o(h,{id:"mermaid-439",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:s(()=>[...d[1]||(d[1]=[a(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=i('<h3 id="lørdag-heldag-teori-praksis" tabindex="-1">Lørdag (Heldag - Teori + Praksis) <a class="header-anchor" href="#lørdag-heldag-teori-praksis" aria-label="Permalink to &quot;Lørdag (Heldag - Teori + Praksis)&quot;">​</a></h3><p><strong>08:00–09:00 – Frokost og mindfulness</strong></p><ul><li>Rolig frokost</li><li>Valgfri 15-minutters guidet meditasjon</li><li>Sett intensjoner for dagen</li></ul><p><strong>09:00–10:30 – Teoriøkt: Koble innhold til opplevelse</strong></p><p>Velg 3–4 emner fra akademiets nettside og utforsk det indre spillet:</p><p><strong>Eksempler på emner:</strong></p><ol><li><p><strong><a href="./utdanning/ernæring/">Ernæring</a></strong> (20 min) – «Hvordan endrer matvalget ditt seg under press?» – «Spiser du det kroppen din trenger, eller det angsten din vil ha?»</p><ul><li>Øvelse: Planlegg ernæring på konkurransedagen</li></ul></li><li><p><strong><a href="./utdanning/mental-styrke/">Mental styrke</a></strong> (25 min) – «Hva er ditt forhold til fiasko?» – «Hvordan snakker du til deg selv etter en bom?»</p><ul><li>Aktivitet: Omformuler indre kritiker til indre coach</li></ul></li><li><p><strong><a href="./utdanning/mindfulness/">Mindfulness</a></strong> (25 min) – «Hvor går tankene dine i pausen før du kaster?» – «Hva trekker deg ut av nåtiden?»</p><ul><li>Øvelse: 5-minutters kroppsskanning</li></ul></li><li><p><strong><a href="./utdanning/taktikk/">Taktikk</a></strong> (20 min) – «Er skuddvalget ditt basert på strategi eller frykt?» – «Når spiller man det trygt kontra å ta risikoer?»</p><ul><li>Diskuter: Risikoprofiler i gruppen</li></ul></li></ol><p><strong>10:30–10:45 – Pause</strong></p><p><strong>10:45–12:30 – Integrering i løypa: Øvelser med mentalt fokus</strong></p><p><strong>Øvelse 1: Ta din sjanse (30 min)</strong></p><p>Fra <a href="./workshop">Workshop-guiden</a> – øv på å eie intensjon og tvil:</p><ol><li>Kunngjør målet: «Jeg skyter med jernet»</li><li>Oppgi selvtillit: «Jeg får 7 av 10»</li><li>Navngi den indre tanken: «Min indre stemme bekymrer seg for bakspinn»</li><li>Utfør skuddet</li><li>Reflekter: «Hva skjedde? Hva lærte du?»</li></ol><p><strong>Øvelse 2: Kognitiv interferens (30 min)</strong></p><p>Test om teknikken har blitt automatisk:</p><ul><li>Koordinator stiller komplekse spørsmål mens spilleren skyter</li><li>&quot;Nevn 5 hovedsteder&quot; eller &quot;Tell baklengs fra 100 med 7&quot;</li><li>Suksess = teknikk er implisitt, ikke bevisst bearbeidet</li></ul><p><strong>Øvelse 3: Brukermanualøvelse (30 min)</strong></p><p>Bruk brukerhåndbøkene fra fredag:</p><ul><li>Spill i lag på 3</li><li>Etter hvert skudd svarer lagkameratene i henhold til brukerhåndboken – «Marc trenger stillhet etter en bom» – laget ærer det</li><li>Oppsummering: «Hvordan føltes det å bli forstått?»</li></ul><p><strong>12:30–14:00 – Lunsj og hvile</strong></p><ul><li>Ernæringsfokusert måltid</li><li>Stille tid for refleksjon</li><li>Valgfritt: Individuelle innsjekkinger med koordinator</li></ul><p><strong>14:00–17:00 – Øving: Terrengtilpasning</strong></p><p><strong>Mål:</strong> Bygge tilpasningsevne og mental fleksibilitet</p><p><strong>Oppsett:</strong></p><ul><li>Roter gjennom 3-4 forskjellige terreng/løyper</li><li>45 minutter per terreng</li><li>Fokus på mental tilpasning, ikke bare teknisk</li></ul><p><strong>Rotasjonsstruktur:</strong></p><table tabindex="0"><thead><tr><th>Terreng</th><th>Mentalt fokus</th><th>Øvelse</th></tr></thead><tbody><tr><td><strong>Terreng 1: Mykt/Sand</strong></td><td>Aksept av usikkerhet</td><td>&quot;Den uerfarne - aksepter det som er&quot;</td></tr><tr><td><strong>Terreng 2: Hardt/Grus</strong></td><td>Presisjon under press</td><td>&quot;Stol på teknikken din&quot;</td></tr><tr><td><strong>Terreng 3: Ujevn</strong></td><td>Emosjonsregulering</td><td>&quot;Vær rolig når det er urettferdig&quot;</td></tr><tr><td><strong>Terreng 4: Konkurranse</strong></td><td>Tilgang til flyttilstand</td><td>&quot;Finn sonen&quot;</td></tr></tbody></table><p><strong>Tilrettelegging:</strong></p><ul><li>Teknisk trener gir tilbakemelding på teknikk – MPC spør: «Hva skjer i tankene dine akkurat nå?»</li><li>Spillerjournal mellom rotasjoner</li></ul><p><strong>17:00–18:00 – Pause og refleksjon</strong></p><ul><li>Individuell journalføring – «Hva lærte du om deg selv i dag?» – «Hva er én ting du vil gjøre annerledes i morgen?»</li></ul><p><strong>18:00–19:00 – Middag</strong></p><p><strong>19:00–21:00 – Kveldsteori: Dyp sårbarhet</strong></p><p><strong>Aktivitet 1: Å omformulere den indre kritikeren (45 min)</strong></p><p>Se <a href="./workshop">Verkstedsveiledning</a> for fullstendig protokoll:</p><ol><li>Identifiser den nøyaktige kritikerfrasen</li><li>Omformuler som indre coach</li><li>Partnerpraksis</li></ol><p><strong>Aktivitet 2: Konkurranseforberedelse (45 min)</strong></p><p>I morgen er det konkurransedag. Forbered deg mentalt:</p><ol><li><p><strong>Visualisering (15 min)</strong></p><ul><li>Lukk øynene</li><li>Se for deg et perfekt skudd</li><li>Føl selvtilliten</li><li>Legg merke til roen</li></ul></li><li><p><strong>Teamprotokoller (20 min)</strong></p><ul><li>Lag signaler for støtte</li><li>&quot;Jeg trenger en tilbakestilling&quot; = berør boules</li><li>«Jeg trenger oppmuntring» = knyttnevestøt</li><li>«Jeg trenger plass» = et skritt tilbake</li></ul></li><li><p><strong>Sett intensjoner (10 min)</strong> – «I morgen skal jeg fokusere på …» – «Målet mitt er ikke å vinne, men å ...» – «Jeg skal øve meg …»</p></li></ol><p><strong>Utsjekking (30 min)</strong></p><ul><li>Del én frykt om morgendagen</li><li>Del én intensjon</li><li>Gruppestøtte</li></ul><p><strong>21:00 - Fritid</strong></p><ul><li>Tidlig i seng (konkurranse i morgen!)</li><li>Stille refleksjon</li></ul><h3 id="søndag-konkurransedag" tabindex="-1">Søndag (konkurransedag) <a class="header-anchor" href="#søndag-konkurransedag" aria-label="Permalink to &quot;Søndag (konkurransedag)&quot;">​</a></h3><p><strong>08:00–09:00 – Frokost og mental forberedelse</strong></p><ul><li>Lett frokost (se <a href="./education/nutrition/">Ernæringsveiledning</a>)</li><li>15-minutters mindfulness-øvelse</li><li>Teammøter</li></ul><p><strong>09:00–09:30 – Konkurransebriefing</strong></p><p><strong>Format:</strong> Round-robin-turnering</p><ul><li>Lag på 3</li><li>Spill til 13 poeng</li><li>Alle spiller alle</li><li>Fokuser på PROSESS, ikke resultat</li></ul><p><strong>Twist: Mental ytelsespoengsum</strong></p><div class="tip custom-block"><p class="custom-block-title">dobbelt poengsystem</p><p><strong>Tradisjonell:</strong> Poeng vunnet <strong>Mental ytelse:</strong> Poengbestemt av MPC</p><p>Mentale prestasjonspoeng (0–5 per kamp):</p><ul><li>Brukte brukerhåndbokverktøy</li><li>Støttet lagkamerater effektivt</li><li>Håndtert indre kritiker</li><li>Forble til stede (ikke dvele ved tidligere bilder)</li><li>Dokumentert psykologisk trygghet</li></ul><p><strong>Vinner:</strong> Beste kombinerte poengsum (tradisjonell + mental)</p></div><p><strong>09:30–13:00 – Morgenkonkurranse</strong></p><ul><li>Round-robin-spill</li><li>MPC observerer og scorer</li><li>Teknisk trener gir kort tilbakemelding mellom kampene</li><li>Hydrering og mellommåltider</li></ul><p><strong>13:00–14:00 – Lunsj</strong></p><ul><li>Ernæringsfokusert</li><li>Uformell refleksjon</li><li>Hvile</li></ul><p><strong>14:00–17:00 – Ettermiddagskonkurranse</strong></p><ul><li>Fortsett runde-robin</li><li>Semifinaler og finaler</li><li>Økende press</li><li>Bruk morgenlærdommene</li></ul><p><strong>17:00–17:30 – Priser og anerkjennelse</strong></p><p><strong>Kategorier:</strong></p><ul><li>Tradisjonell vinner</li><li>Vinner av mental ytelse</li><li>Mest forbedret</li><li>Beste lagkamerat</li><li>Motpris (mest sårbare)</li></ul><p><strong>17:30–19:00 – Avsluttende refleksjonsøkt</strong></p><p><strong>Kritisk:</strong> Det er her læring sementeres.</p><p><strong>Struktur:</strong></p><p><strong>1. Individuell refleksjon (15 min)</strong> Skriv i journalen: – Hva lærte du om deg selv i helgen? – Hva overrasket deg? – Hva vil du gjøre annerledes? – Hva tar du med deg hjem?</p><p><strong>2. Gruppedeling i liten gruppe (30 min)</strong> Grupper på 4-5:</p><ul><li>Del viktige innsikter – Hva resonnerte mest? – Hva var vanskeligst? – Hva var mest verdifullt?</li></ul><p><strong>3. Full gruppeintegrasjon (30 min)</strong> Ring opp:</p><ul><li>Hver person deler ÉN viktig lærdom</li><li>MPC validerer og kobler sammen temaer</li><li>Diskuter: «Hvordan vil dere bruke dette?»</li></ul><p><strong>4. Forpliktelser (15 min)</strong></p><ul><li>Hver person forplikter seg én gang – «I min neste konkurranse skal jeg …»</li><li>Gruppevitner og støttespillere</li></ul><p><strong>5. Avslutning (15 min)</strong></p><ul><li>Takk deltakerne for motet</li><li>Minn om taushetsplikt</li><li>Utveksle kontakter</li><li>Planlegg oppfølging (valgfri online-sesjon)</li></ul><p><strong>19:00 - Middag og avreise</strong></p><h2 id="tilretteleggingstips" tabindex="-1">Tilretteleggingstips <a class="header-anchor" href="#tilretteleggingstips" aria-label="Permalink to &quot;Tilretteleggingstips&quot;">​</a></h2><h3 id="balanse-mellom-teori-og-praksis" tabindex="-1">Balanse mellom teori og praksis <a class="header-anchor" href="#balanse-mellom-teori-og-praksis" aria-label="Permalink to &quot;Balanse mellom teori og praksis&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Ikke overbelast teorien</p><p><strong>Feilen:</strong> For mye snakk, ikke nok handling</p><p><strong>Saldoen:</strong></p><ul><li>Teori skaper bevissthet</li><li>Øvelse bygger ferdigheter</li><li>Integrering av konkurransetester</li><li>Refleksjon sementerer læring</li></ul><p><strong>Tommelfingerregel:</strong> 30 % teori, 40 % praksis, 20 % konkurranse, 10 % refleksjon</p></div><h3 id="handtering-av-gruppedynamikk" tabindex="-1">Håndtering av gruppedynamikk <a class="header-anchor" href="#handtering-av-gruppedynamikk" aria-label="Permalink to &quot;Håndtering av gruppedynamikk&quot;">​</a></h3><p><strong>Den konkurransedyktige alfaen:</strong> – Vil vinne for enhver pris</p><ul><li>Motstår sårbarhet</li><li><strong>Strategi:</strong> Kanaliser konkurranseevne inn i mental prestasjonsscoring</li></ul><p><strong>Den stille observatøren:</strong></p><ul><li>Tar alt inn, deler ikke</li><li><strong>Strategi:</strong> Lag inngangspunkter med lav innsats, valider observasjon som deltakelse</li></ul><p><strong>Skeptikeren:</strong> – «Denne følsomme greia fungerer ikke»</p><ul><li><strong>Strategi:</strong> Verbal Aikido - innrett og drei (se <a href="./workshop">Workshop-guide</a>)</li></ul><p><strong>Overdeleren:</strong></p><ul><li>Dominerer diskusjonen</li><li><strong>Strategi:</strong> «Takk, la oss høre fra andre»</li></ul><h3 id="handtering-av-emosjonelle-øyeblikk" tabindex="-1">Håndtering av emosjonelle øyeblikk <a class="header-anchor" href="#handtering-av-emosjonelle-øyeblikk" aria-label="Permalink to &quot;Håndtering av emosjonelle øyeblikk&quot;">​</a></h3><p><strong>Noen gråter under Frykt i hatten:</strong></p><ul><li>✅ Normaliser: «Tårer er mot, ikke svakhet»</li><li>✅ Tilby papirservietter, ikke forhast deg</li><li>✅ Spør: «Hva trenger du akkurat nå?»</li><li>❌ Ikke gjør det: «Det er greit, ikke gråt»</li></ul><p><strong>Konflikt mellom spillere:</strong></p><ul><li>✅ Pause og adressering – ✅ «Hva skjer akkurat nå?»</li><li>✅ Bruk som læringsøyeblikk</li><li>❌ Ikke: Ignorer eller minimer</li></ul><p><strong>Noen slår av:</strong></p><ul><li>✅ Sjekk inn privat i pausen</li><li>✅ «Jeg la merke til at du ble stille. Hva skjer?»</li><li>✅ Tilbudsalternativer: delta annerledes, ta en pause</li><li>❌ Ikke: Ring ut offentlig</li></ul><h2 id="oppfølging-etter-leiren" tabindex="-1">Oppfølging etter leiren <a class="header-anchor" href="#oppfølging-etter-leiren" aria-label="Permalink to &quot;Oppfølging etter leiren&quot;">​</a></h2><h3 id="umiddelbar-24–48-timer" tabindex="-1">Umiddelbar (24–48 timer) <a class="header-anchor" href="#umiddelbar-24–48-timer" aria-label="Permalink to &quot;Umiddelbar (24–48 timer)&quot;">​</a></h3><p><strong>Send til alle deltakere:</strong></p><ul><li>Takkemelding</li><li>Sammendrag av viktige poenger</li><li>Bilder fra helgen</li><li>Kontaktliste (med tillatelse)</li><li>Lenke til ressurser på nettsiden</li></ul><p><strong>Individuelle innsjekkinger:</strong></p><ul><li>Send melding til alle som delte mye – «Hvordan føler du deg om helgen?»</li><li>Ta tak i eventuelle sårbarhetsproblemer</li></ul><h3 id="kortsiktig-2-uker" tabindex="-1">Kortsiktig (2 uker) <a class="header-anchor" href="#kortsiktig-2-uker" aria-label="Permalink to &quot;Kortsiktig (2 uker)&quot;">​</a></h3><p><strong>Valgfri nettbasert økt (60–90 min):</strong> – Hvordan har du anvendt lærdommene? – Hva fungerer? Hva er utfordrende?</p><ul><li>Likemannsstøtte og problemløsning</li><li>Forsterke forpliktelser</li></ul><h3 id="langsiktig-1–3-maneder" tabindex="-1">Langsiktig (1–3 måneder) <a class="header-anchor" href="#langsiktig-1–3-maneder" aria-label="Permalink to &quot;Langsiktig (1–3 måneder)&quot;">​</a></h3><p><strong>Deltakere i undersøkelsen:</strong> – Hva er annerledes i spillet ditt? – Hvilke verktøy bruker du fortsatt? – Hva ville gjort den neste leiren bedre? – Ville du anbefalt det til andre?</p><p><strong>Påvirkning av banen:</strong></p><ul><li>Konkurranseresultater</li><li>Selvrapportert selvtillit</li><li>Teamdynamikk</li><li>Fortsatt engasjement</li></ul><h2 id="tilpasning-for-ulike-gruppestørrelser" tabindex="-1">Tilpasning for ulike gruppestørrelser <a class="header-anchor" href="#tilpasning-for-ulike-gruppestørrelser" aria-label="Permalink to &quot;Tilpasning for ulike gruppestørrelser&quot;">​</a></h2><h3 id="liten-leir-10–12-spillere" tabindex="-1">Liten leir (10–12 spillere) <a class="header-anchor" href="#liten-leir-10–12-spillere" aria-label="Permalink to &quot;Liten leir (10–12 spillere)&quot;">​</a></h3><p><strong>Fordeler:</strong></p><ul><li>Dypere deling</li><li>Mer individuell oppmerksomhet</li><li>Sterkere bånd</li></ul><p><strong>Justeringer:</strong></p><ul><li>Én gruppe for all teori</li><li>Mer tid per person til aktiviteter</li><li>Intimt konkurranseformat</li></ul><h3 id="stor-leir-16–20-spillere" tabindex="-1">Stor leir (16–20 spillere) <a class="header-anchor" href="#stor-leir-16–20-spillere" aria-label="Permalink to &quot;Stor leir (16–20 spillere)&quot;">​</a></h3><p><strong>Fordeler:</strong></p><ul><li>Ulike perspektiver</li><li>Mer variasjon i konkurranser</li><li>Stordriftsfordeler</li></ul><p><strong>Justeringer:</strong></p><ul><li>Del inn i to grupper for noen teoriøkter</li><li>Trenger 2 MPC/tilretteleggere</li><li>Større turneringsramme</li><li>Mer strukturerte rotasjoner</li></ul><h2 id="budsjetthensyn" tabindex="-1">Budsjetthensyn <a class="header-anchor" href="#budsjetthensyn" aria-label="Permalink to &quot;Budsjetthensyn&quot;">​</a></h2><h3 id="inntekter" tabindex="-1">Inntekter <a class="header-anchor" href="#inntekter" aria-label="Permalink to &quot;Inntekter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vare</th><th>Pris per person</th><th>20 personer</th><th>10 personer</th></tr></thead><tbody><tr><td><strong>Registrering</strong></td><td>€150–250</td><td>€3 000–5 000</td><td>€1 500–2 500</td></tr></tbody></table><h3 id="utgifter" tabindex="-1">Utgifter <a class="header-anchor" href="#utgifter" aria-label="Permalink to &quot;Utgifter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kategori</th><th>Kostnad</th><th>Merknader</th></tr></thead><tbody><tr><td><strong>Leie av lokaler</strong></td><td>€500–1000</td><td>Helgepris</td></tr><tr><td><strong>Overnatting</strong></td><td>€40–60/person/natt</td><td>Delte rom</td></tr><tr><td><strong>Måltider</strong></td><td>€30–40/person/dag</td><td>6 måltider</td></tr><tr><td><strong>Ansatte</strong></td><td>€500–1000</td><td>MPC + trenere</td></tr><tr><td><strong>Materialer</strong></td><td>€100–200</td><td>Arbeidsark, rekvisita</td></tr><tr><td><strong>Premier</strong></td><td>€100–200</td><td>Anerkjennelsesartikler</td></tr></tbody></table><p><strong>Totalt per person:</strong> €120–180 <strong>Margin:</strong> €30–70/person (eller nullpunkt for fellesskapsbygging)</p><h2 id="suksessmalinger" tabindex="-1">Suksessmålinger <a class="header-anchor" href="#suksessmalinger" aria-label="Permalink to &quot;Suksessmålinger&quot;">​</a></h2><h3 id="umiddelbare-indikatorer" tabindex="-1">Umiddelbare indikatorer <a class="header-anchor" href="#umiddelbare-indikatorer" aria-label="Permalink to &quot;Umiddelbare indikatorer&quot;">​</a></h3><ul><li>[] Psykologisk sikkerhetspoengsum (gjennomsnitt 1–10 &gt;7)</li><li>[ ] Deltakelsesrate (&gt;80 % deler aktivt)</li><li>[ ] Fullføringsgrad (&gt;90 % oppholder seg hele helgen)</li><li>[ ] Tilfredshetspoengsum (gjennomsnitt 1–10 &gt;8)</li></ul><h3 id="langsiktige-indikatorer" tabindex="-1">Langsiktige indikatorer <a class="header-anchor" href="#langsiktige-indikatorer" aria-label="Permalink to &quot;Langsiktige indikatorer&quot;">​</a></h3><ul><li>[ ] Atferdsendring (ved bruk av verktøy i konkurranse)</li><li>[ ] Prestasjonsforbedring (selvrapportert)</li><li>[ ] Fellesskapsbygging (holde kontakten)</li><li>[ ] Anbefalinger (anbefalinger til andre)</li></ul><h2 id="vanlige-feil-a-unnga" tabindex="-1">Vanlige feil å unngå <a class="header-anchor" href="#vanlige-feil-a-unnga" aria-label="Permalink to &quot;Vanlige feil å unngå&quot;">​</a></h2><p>::: fare Fallgruver <strong>1. For mye innhold</strong> – Prøver å dekke over alt</p><ul><li><strong>Rettelse:</strong> Fokuser på dybde, ikke bredde</li></ul><p><strong>2. Hoppe over refleksjon</strong></p><ul><li>Skynder seg til neste aktivitet</li><li><strong>Rettelse:</strong> Innebygd behandlingstid</li></ul><p><strong>3. Ignorerer motstand</strong></p><ul><li>Å overvinne skepsis</li><li><strong>Fiksing:</strong> Ta det opp direkte med verbal aikido</li></ul><p><strong>4. Teknisk veiledning under teorien</strong></p><ul><li>Blanding av roller</li><li><strong>Rettelse:</strong> Tydelige grenser mellom MPC og teknisk trener</li></ul><p><strong>5. Ingen oppfølging</strong></p><ul><li>Helgen er over, læringen stopper</li><li><strong>Rettelse:</strong> Planlegg kontaktpunkter etter leiren :::</li></ul><h2 id="ressurser" tabindex="-1">Ressurser <a class="header-anchor" href="#ressurser" aria-label="Permalink to &quot;Ressurser&quot;">​</a></h2><h3 id="fra-dette-nettstedet" tabindex="-1">Fra dette nettstedet <a class="header-anchor" href="#fra-dette-nettstedet" aria-label="Permalink to &quot;Fra dette nettstedet&quot;">​</a></h3><ul><li><a href="./workshop">Workshopguide</a> - Detaljerte tilretteleggingsprotokoller</li><li><a href="./training-session">Veiledning for treningsøkt</a> - For kontinuerlig øving</li><li><a href="./utdanning/ernæring/">Ernæring</a> - Protokoller for konkurransedagen</li><li><a href="./utdanning/mental-styrke/">Mental styrke</a> - Indre spillkonsepter</li><li><a href="./utdanning/mindfulness/">Mindfulness</a> - Nærværsteknikker</li><li><a href="./utdanning/taktikk/">Taktikk</a> - Strategisk tenkning</li></ul><h3 id="anbefalt-lesestoff" tabindex="-1">Anbefalt lesestoff <a class="header-anchor" href="#anbefalt-lesestoff" aria-label="Permalink to &quot;Anbefalt lesestoff&quot;">​</a></h3><ul><li><em>Tennisens indre spill</em> av Timothy Gallwey</li><li><em>Tankegang</em> av Carol Dweck</li><li><em>Den fryktløse organisasjonen</em> av Amy Edmondson</li></ul>',142))])}]]);export{d as __pageData,k as default};
